#!/usr/bin/env node
/** 评估 VLM 并发容量（§2 调参依据）+ 卡滞任务清理安全性（§3 依据）。Read-only. */
const B = 'http://127.0.0.1:1933';
const VLM = 'http://127.0.0.1:3425/v1/chat/completions';
async function get(p) { try { const r = await fetch(B + p, { signal: AbortSignal.timeout(12000) }); const t = await r.text(); let j = null; try { j = JSON.parse(t); } catch {} return { s: r.status, j, t }; } catch (e) { return { s: 0, j: null, t: 'ERR ' + e.message }; } }

// ---------- §2: VLM capacity probe ----------
console.log('=== §2 VLM 并发容量评估 ===');
console.log('配置: vlm.max_concurrent=4, api_base=http://127.0.0.1:3425/v1 (magpie auto/hy3)');
let lat = [];
for (let i = 0; i < 3; i++) {
  const t0 = Date.now();
  try {
    const r = await fetch(VLM, { method: 'POST', headers: { Authorization: 'Bearer magpie', 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'auto/hy3', messages: [{ role: 'user', content: 'reply ok' }], max_tokens: 8 }), signal: AbortSignal.timeout(60000) });
    const j = await r.json(); const txt = j.choices?.[0]?.message?.content || j.choices?.[0]?.message?.reasoning_content || '';
    lat.push(Date.now() - t0);
    console.log('  probe' + (i + 1) + ' HTTP ' + r.status + ' ' + (Date.now() - t0) + 'ms ok=' + !!txt);
  } catch (e) { console.log('  probe' + (i + 1) + ' ERR ' + e.message); }
}
if (lat.length) { lat.sort((a, b) => a - b); console.log('  单请求延迟: min=' + lat[0] + 'ms p50=' + lat[Math.floor(lat.length / 2)] + 'ms max=' + lat[lat.length - 1] + 'ms'); }

// concurrent probe: 6 parallel (exceeds max_concurrent=4) to see queueing/backpressure
console.log('  并发探针: 6 个并行请求（观测 3425 是否能承受 >4）...');
const tc = Date.now();
const results = await Promise.allSettled(Array.from({ length: 6 }, (_, i) => (async () => {
  const t = Date.now();
  const r = await fetch(VLM, { method: 'POST', headers: { Authorization: 'Bearer magpie', 'Content-Type': 'application/json' }, body: JSON.stringify({ model: 'auto/hy3', messages: [{ role: 'user', content: 'reply ' + i }], max_tokens: 8 }), signal: AbortSignal.timeout(90000) });
  const j = await r.json(); const txt = j.choices?.[0]?.message?.content || j.choices?.[0]?.message?.reasoning_content || '';
  return { i, status: r.status, ms: Date.now() - t, ok: !!txt };
})()));
const ok = results.filter(x => x.status === 'fulfilled' && x.value.ok);
console.log('  6 并发: 成功=' + ok.length + '/6, 墙钟=' + (Date.now() - tc) + 'ms, 各请求延迟=' + JSON.stringify(results.map(x => x.status === 'fulfilled' ? x.value.ms : 'ERR')));
console.log('  判读: 若 6 并发全部成功且墙钟接近单个延迟→后端有空余容量，可上调 max_concurrent；若显著线性变长/报错→后端已饱和，维持 4。');

// ---------- §3: stuck task cleanup safety ----------
console.log('\n=== §3 卡滞任务清理安全性评估 ===');
const t = await get('/api/v1/tasks');
const tasks = Array.isArray(t.j?.result) ? t.j.result : [];
const now = Date.now() / 1000;
const running = tasks.filter(x => x.status === 'running');
const stale = running.filter(x => x.updated_at && (now - x.updated_at) > 900);
console.log('running=' + running.length + ' stale(>900s)=' + stale.length);
for (const x of stale) {
  const d = await get('/api/v1/tasks/' + x.task_id);
  const r = d.j?.result || {};
  const me = r.result?.memories_extracted || null;
  const sid = (r.resource_id || '').replace(/^dsh-session-/, '');
  let sessionState = null;
  if (sid) { const sd = await get('/api/v1/stats/sessions/' + encodeURIComponent('dsh-session-' + sid)); sessionState = sd.s + ' ' + JSON.stringify(sd.j?.result); }
  console.log('  task=' + x.task_id);
  console.log('    secs=' + Math.round(r.processing_seconds || 0) + ' updated=' + new Date((r.updated_at || 0) * 1000 + 8 * 3600e3).toISOString().slice(11, 19) + ' 距今=' + Math.round(now - (r.updated_at || 0)) + 's');
  console.log('    stage=' + r.stage + ' result.memories_extracted=' + JSON.stringify(me));
  console.log('    session=' + sid + ' stats=' + sessionState);
  // is memory already visible? check sessions archive
  const ar = await get('/api/v1/sessions/' + encodeURIComponent('dsh-session-' + sid));
  console.log('    session_record=' + ar.s + ' ' + JSON.stringify(ar.j?.result || ar.t.slice(0, 120)).slice(0, 200));
}

