/** 确认卡滞任务对应 session 的归档是否已落地 + 记忆是否可检索。Read-only. */
const B = 'http://127.0.0.1:1933';
async function get(p) { try { const r = await fetch(B + p, { signal: AbortSignal.timeout(15000) }); const t = await r.text(); let j = null; try { j = JSON.parse(t); } catch {} return { s: r.status, j, t }; } catch (e) { return { s: 0, j: null, t: 'ERR ' + e.message }; } }
const SID = 'dsh-session-2645d33b-6d97-4c8d-af1d-5a7b8e5a2935';
const d = await get('/api/v1/tasks/e5c4be47-5251-4c37-bf0f-7ed01cc9b555');
const r = d.j?.result || {};
console.log('=== 卡滞任务结果字段全量 ===');
console.log(JSON.stringify(r.result || {}, null, 1).slice(0, 1200));
const arc = (r.result || {}).archive_uri;
console.log('\narchive_uri=' + arc);
if (arc) {
  const info = await get('/api/v1/fs/stat?uri=' + encodeURIComponent(arc));
  console.log('archive stat: ' + info.s + ' ' + JSON.stringify(info.j?.result || info.t.slice(0, 200)).slice(0, 300));
  const ls = await get('/api/v1/fs/ls?uri=' + encodeURIComponent(arc));
  console.log('archive ls: ' + ls.s + ' ' + JSON.stringify(ls.j?.result || ls.t.slice(0, 200)).slice(0, 400));
}
// 该会话消息是否已入库
const msgs = await get('/api/v1/sessions/' + encodeURIComponent(SID) + '/context');
console.log('\nsession context: ' + msgs.s + ' ' + JSON.stringify(msgs.j?.result || msgs.t.slice(0, 200)).slice(0, 400));

